import { NextResponse } from 'next/server';
import fs from 'fs';
import path from 'path';

export async function GET() {
  try {
    // Read the crosscut-results.json generated by the CLI in the repository root
    // Going up from dashboard/src/app/api/results -> dashboard -> repo root
    const resultsPath = path.join(process.cwd(), '..', 'crosscut-results.json');
    
    if (!fs.existsSync(resultsPath)) {
      return NextResponse.json({ 
        error: "No results found. Run 'crosscut' CLI to generate crosscut-results.json." 
      }, { status: 404 });
    }

    const data = fs.readFileSync(resultsPath, 'utf8');
    return NextResponse.json(JSON.parse(data));
  } catch (error) {
    console.error("Error reading crosscut-results.json:", error);
    return NextResponse.json({ error: "Failed to read results" }, { status: 500 });
  }
}
